] = { -- 2 экстраординарных + 1 обычный\n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 1790, min = 0,90, max = 1,10},\n p70 = {score = 2034, min = 1,10, max = 1,30},\n p90 = {score = 2278, min = 1,30, max = 1,50},\n базовая цена = 2000000\n },\n [1] = { -- 1 экстраординарный + 2 обычных \n По умолчанию = {min = 0,70, max = 0,90}, \n p50 = {score = 1255, min = 0,90, max = 1,10}, \n p70 = {score = 1473, min = 1,10, max = 1,30},\n p90 = {score = 1691, min = 1,30, max = 1,50},\n baseprice = 500000\n },\n [0] = { -- 3Normal\n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {оценка = 720, мин = 0,90, макс = 1,10},\n p70 = {оценка = 912, мин = 1,10, макс = 1,30},\n p90 = {оценка = 1104, мин = 1,30, макс = 1,50},\n базовая цена = 200000\n }\n },\n [2] = {\n [2] = { -- 2 чрезвычайных \n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 1550, min = 0,90, max = 1,10},\n p70 = {score = 1730, min = 1,10, max = 1,30},\n p90 = {score = 1910, min = 1,30, max = 1,50},\n baseprice = 1500000\n },\n [1] = { -- 1 экстраординарный + 1 обычный \n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 1015, min = 0,90, max = 1,10}, \n p70 = {score = 1169, min = 1,10, max = 1,30}, \n p90 = {score = 1323, min = 1,30, макс = 1,50},\n baseprice = 200000\n },\n [0] = { -- 2Normal\n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 480, min = 0,90, max = 1,10},\n p70 = {score = 608, min = 1,10, max = 1,30},\n p90 = {score = 736, min = 1,30, max = 1,50},\n baseprice = 100000\n }\n },\n [1] = {\n [1] = { -- 1 экстраординарный \n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 775, min = 0,90, max = 1,10},\n p70 = {score = 865, min = 1,10, max = 1,30},\n p90 = {score = 955, min = 1,30, max = 1,50},\n baseprice = 100000\n },\n [0] = { -- 1Normal\n По умолчанию = {min = 0,70, max = 0,90},\n p50 = {score = 240, min = 0,90, макс = 1,10},\n p70 = {оценка = 304, мин = 1,10, макс = 1,30},\n p90 = {оценка = 368, мин = 1,30, макс = 1,50},\n базовая цена = 50000\n }\n }\n}\n\nlocal data = coeffData[$2] и coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nесли нет данных, то\n minCoeff = 0,5\n maxCoeff = 1,5\n базовая цена = 10000000\nelseif $1 > data.p90.score then\n minCoeff, maxCoeff = data.p90.min, data.p90.max\n baseprice = data.baseprice\nelseif $1 > data.p70.score then\n minCoeff, maxCoeff = data.p70.min, data.p70.max\n baseprice = data.baseprice\nelseif $1 > data.p50.score then\n minCoeff, maxCoeff = data.p50.min, data.p50.max\n baseprice = data.baseprice\nelse\n minCoeff, maxCoeff = data.Default.min, data.Default.max\n baseprice = data.baseprice\nend\n\nlocal Step = 0,05\nlocal Steps = Floor((maxCoeff - minCoeff) / шаг + 0,5)\nlocal randIndex = Random(0,steps)\nlocal result = minCoeff + randIndex * шаг\n\nreturn Round(Floor(result * 100 + 0,5) / 100 * базовая цена + 4 доллара США)",
